const ServiceNowFieldMappingSchema = z
  .object({
    servicenow_field: z
      .string()
      .openapi({
        description:
          'The ServiceNow field (column) to read the value from. Dot-walked fields are supported to traverse relationships (for example, `support_group.manager.email`).',
      }),
    event_field: z
      .string()
      .openapi({ description: 'The event field that the ServiceNow value is mapped to.' }),
    type: z
      .enum(['query', 'enriched', 'discriminator'])
      .exactOptional()
      .openapi({
        description:
          "Determines how the field is used during enrichment. `enriched` fields add contextual data to a matched event, while `query` fields are used to match incoming events to Configuration Items. When no mapping specifies a `type`, the field defaults to `enriched` and the `name` field is automatically used as the single query field. To match on a different field — or on more than one field — set `type: query` on those mappings; in that mode `name` is no longer used as a query field unless it is itself marked `query`. Up to 3 query fields may be configured, and when more than one is set an event must contain a matching value for every query field to be enriched (logical AND). At least one mapping must be an enriched field. In responses, a mapping's `type` is `query`, `enriched`, or `discriminator`. `discriminator` is assigned automatically to the `sys_id` field of `cmdb_rel_ci` relationship tables to distinguish relationship types; it appears in responses but cannot be set on requests.",
      }),
  })
  .openapi({ required: ['servicenow_field', 'event_field'] })
  .openapi('ServiceNowFieldMapping')

