const EnrichmentFieldSchema = z
  .object({
    name: z
      .string()
      .max(256)
      .openapi({
        description: 'The name of the field. Unique within the schema (case-insensitive).',
      }),
    type: z
      .enum(['query', 'enriched', 'discriminator'])
      .openapi({
        description:
          'How the field is used during enrichment. `query` fields are used to match incoming events to enrichment records (matching is case-insensitive), and `enriched` fields carry the contextual data added to a matched event. A schema has 1-3 query fields and at least one enriched field. `discriminator` is reserved for internal use (for example, by the ServiceNow CMDB integration).',
      }),
  })
  .openapi({ required: ['name', 'type'] })
  .openapi('EnrichmentField')

const EnrichmentSchemaSchema = z
  .object({
    id: z
      .uuid()
      .exactOptional()
      .openapi({ readOnly: true, description: 'Unique identifier for the enrichment schema.' }),
    type: z
      .string()
      .exactOptional()
      .openapi({
        readOnly: true,
        description: 'The type of the resource.',
        example: 'enrichment_schema',
      }),
    integration_type: z
      .enum(['CSV', 'SERVICENOW'])
      .exactOptional()
      .openapi({
        readOnly: true,
        description:
          'The source of the enrichment schema. `CSV` schemas are created and populated through the schema and CSV-upload endpoints; `SERVICENOW` schemas are managed by the ServiceNow CMDB integration. Schemas created through the API are always `CSV`, and only `CSV` schemas can be deleted.',
      }),
    name: z
      .string()
      .max(50)
      .exactOptional()
      .openapi({ description: 'Display name of the enrichment schema.' }),
    description: z
      .string()
      .max(2048)
      .nullable()
      .exactOptional()
      .openapi({ description: 'Description of this set of enrichment data.' }),
    fields: z
      .array(EnrichmentFieldSchema)
      .min(2)
      .max(25)
      .exactOptional()
      .openapi({
        description:
          'The fields that make up the schema, including both query and enriched fields. A schema must contain 1-3 `query` fields and at least one `enriched` field, up to a maximum of 25 fields. Field names are unique within the schema (case-insensitive).',
      }),
    created_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ readOnly: true, description: 'Timestamp when the schema was created.' }),
    updated_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ readOnly: true, description: 'Timestamp when the schema was last updated.' }),
    deleted_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        readOnly: true,
        description: 'Timestamp when the schema was deleted, or `null` if it has not been deleted.',
      }),
  })
  .openapi({ required: [] })
  .openapi('EnrichmentSchema')

const EnrichmentRecordSchema = z
