const SupportHoursSchema = z
  .object({
    type: z
      .literal('fixed_time_per_day')
      .default('fixed_time_per_day')
      .exactOptional()
      .openapi({ description: 'The type of support hours' }),
    time_zone: z
      .string()
      .exactOptional()
      .openapi({ description: 'The time zone for the support hours' }),
    days_of_week: z
      .array(
        z
          .int()
          .openapi({
            readOnly: true,
            description: 'The days of the week (1 through 7, for Monday through Sunday)',
          }),
      )
      .exactOptional()
      .openapi({ readOnly: true }),
    start_time: z
      .string()
      .regex(
        /^(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)?$/,
      )
      .exactOptional()
      .openapi({
        format: 'time',
        description: "The support hours' starting time of day (date portion is ignored)",
      }),
    end_time: z
      .string()
      .regex(
        /^(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)?$/,
      )
      .exactOptional()
      .openapi({
        format: 'time',
        description: "The support hours' ending time of day (date portion is ignored)",
      }),
  })
  .openapi({ required: [] })
  .openapi('SupportHours')

const IncidentNoteSchema = z
  .object({
    id: z.string().exactOptional().openapi({ readOnly: true }),
    user: ReferenceSchema.and(
      z
        .object({ type: z.enum(['user_reference', 'bot_user_reference']).exactOptional() })
        .openapi({
          description:
            'The user who created a Note. If a service created this Note the `user.type` will be "bot_user_reference" and `user.summary` will list the name of the service rather than the user.',
          required: [],
        }),
    ).exactOptional(),
    channel: z
      .object({
        summary: z
          .string()
          .openapi({ description: 'A string describing the source of the Note.', readOnly: true }),
        id: z.string().exactOptional().openapi({ readOnly: true }),
        type: z
          .string()
          .exactOptional()
          .openapi({
            description: 'A string that determines the schema of the object',
            readOnly: true,
          }),
        self: z
          .url()
          .exactOptional()
          .openapi({
            description: 'The API show URL at which the object is accessible',
            readOnly: true,
          }),
        html_url: z
          .url()
          .exactOptional()
          .openapi({
            description: 'a URL at which the entity is uniquely displayed in the Web app',
            readOnly: true,
          }),
      })
      .exactOptional()
      .openapi({
        readOnly: true,
        description:
          'The means by which this Note was created. Has different formats depending on type.',
        required: ['summary'],
      }),
    content: z.string().openapi({ description: 'The note content' }),
    created_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'The time at which the note was submitted', readOnly: true }),
    updated_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'The time at which the note was last updated', readOnly: true }),
  })
  .openapi({ required: ['content'], example: { content: 'Firefighters are on the scene.' } })
  .openapi('IncidentNote')

const NotificationSchema = z
