const ExtensionSchemaSchema = z
  .object({
    icon_url: z
      .url()
      .exactOptional()
      .openapi({ readOnly: true, description: 'A small logo, 18-by-18 pixels.' }),
    logo_url: z
      .url()
      .exactOptional()
      .openapi({
        readOnly: true,
        description: 'A large logo, 75 pixels high and no more than 300 pixels wide.',
      }),
    label: z
      .string()
      .exactOptional()
      .openapi({ readOnly: true, description: 'Human friendly display label' }),
    key: z
      .string()
      .exactOptional()
      .openapi({ readOnly: true, description: 'Machine friendly display label' }),
    description: z
      .string()
      .exactOptional()
      .openapi({ description: 'The long description for the Extension' }),
    guide_url: z
      .url()
      .exactOptional()
      .openapi({ readOnly: true, description: "A link to the extension's support guide" }),
    send_types: z
      .array(
        z.enum([
          'trigger',
          'acknowledge',
          'resolve',
          'delegate',
          'escalate',
          'unacknowledge',
          'assign',
          'custom',
        ]),
      )
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({
        description: 'The types of PagerDuty incident events that will activate this Extension',
      }),
    url: z
      .string()
      .exactOptional()
      .openapi({
        readOnly: true,
        description: 'The url that the webhook payload will be sent to for this Extension.',
      }),
  })
  .openapi({
    example: {
      id: 'PJFWPEP',
      type: 'extension_schema',
      summary: 'Generic Webhook',
      self: 'https://api.pagerduty.com/extension_schemas/PJFWPEP',
      html_url: 'null',
      description: 'Long description here',
      guide_url: 'https://developer.pagerduty.com',
      icon_url: 'https://extension.com/extension.png',
      key: 'generic_webhook',
      label: 'Generic Webhook',
      logo_url: 'https://extension.com/logo.png',
      send_types: [
        'trigger',
        'acknowledge',
        'resolve',
        'delegate',
        'escalate',
        'unacknowledge',
        'assign',
        'custom',
      ],
      url: 'https://developer.pagerduty.com/my_webhook_endpoint',
    },
    required: [],
  })
  .openapi('ExtensionSchema')

