const CidrEntrySchema = z
  .object({
    cidr: z
      .string()
      .regex(
        /^((25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\/([1-9]|[12]\d|3[0-2])$/,
      )
      .openapi({
        description:
          'An IPv4 CIDR range. Each octet must be `0`-`255` and the mask must be between `1` and `32`.',
        example: '192.168.1.0/24',
      }),
    description: z
      .string()
      .max(64)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'An optional human-readable description for the entry. Limited to 64 characters.',
        example: 'Office VPN',
      }),
  })
  .openapi({ description: 'A single CIDR entry within an IP allow list.', required: ['cidr'] })
  .openapi('CidrEntry')

const IpAllowListSchema = z
  .object({
    id: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Unique identifier for the allow list\n(e.g. `AGIS47HYOV6BDODBTMQKMPQPHU`).\n',
        readOnly: true,
      }),
    type: z
      .literal('ip_allow_list')
      .default('ip_allow_list')
      .exactOptional()
      .openapi({
        description: 'A string that determines the schema of the object.',
        readOnly: true,
      }),
    state: z
      .enum(['enabled', 'disabled'])
      .openapi({
        description:
          'Whether the allow list is enforced for the account. When `enabled`, only\nrequests from IPs matching one of the `cidr_entries` are permitted to\naccess the subdomain. When `disabled`, the allow list is stored but not\nenforced.\n',
      }),
    cidr_entries: z
      .array(CidrEntrySchema)
      .max(100)
      .openapi({
        description:
          'The CIDR ranges that are allowed when the allow list is `enabled`. Must\nbe non-empty when `state` is `enabled`.\n',
      }),
  })
  .openapi({
    description:
      "An IP allow list restricts access to a PagerDuty account's subdomain to a set\nof IPv4 CIDR ranges. Enforcement currently applies to web and mobile\napplication traffic.\n",
    required: ['state', 'cidr_entries'],
    example: {
      id: 'AGIS47HYOV6BDODBTMQKMPQPHU',
      type: 'ip_allow_list',
      state: 'enabled',
      cidr_entries: [
        { cidr: '192.168.1.0/24', description: 'Office VPN' },
        { cidr: '10.0.0.0/24', description: 'Data Center' },
      ],
    },
  })
  .openapi('IpAllowList')

