const WebhookSubscriptionSchema = z
  .object({
    id: z.string().exactOptional().openapi({ readOnly: true }),
    type: z
      .literal('webhook_subscription')
      .default('webhook_subscription')
      .openapi({ description: 'The type indicating the schema of the object.' }),
    active: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        description: 'Determines whether this subscription will produce webhook events.',
      }),
    delivery_method: z
      .object({
        id: z.string().exactOptional().openapi({ readOnly: true }),
        secret: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'The secret used to sign webhook payloads. Only provided on the initial create response.',
            readOnly: true,
          }),
        temporarily_disabled: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              'Whether or not this webhook subscription is temporarily disabled. Becomes `true` if the delivery method URL is repeatedly rejected by the server.',
          }),
        type: z
          .literal('http_delivery_method')
          .default('http_delivery_method')
          .openapi({ description: 'Indicates the type of the delivery method.' }),
        url: z.url().openapi({ description: 'The destination URL for webhook delivery.' }),
        custom_headers: z
          .array(
            z
              .object({
                name: z.string().exactOptional().openapi({ description: 'The header name' }),
                value: z.string().exactOptional().openapi({ description: 'The header value' }),
              })
              .openapi({ required: [] }),
          )
          .exactOptional()
          .openapi({
            description:
              "Optional headers to be set on this webhook subscription when sent. The header values are redacted in GET requests, but are not redacted on the webhook when delivered to the webhook's endpoint.",
          }),
      })
      .openapi({ required: ['type', 'url'] }),
    description: z
      .string()
      .exactOptional()
      .openapi({ description: 'A short description of the webhook subscription.' }),
    events: z
      .array(z.string())
      .min(1)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({ description: 'The set of outbound event types the webhook will receive.' }),
    filter: z
      .object({
        id: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'The id of the object being used as the filter.  This field is required for all filter types except account_reference.',
          }),
        type: z
          .enum(['account_reference', 'service_reference', 'team_reference'])
          .openapi({ description: 'The type of object being used as the filter.' }),
      })
      .openapi({ required: ['type'] }),
    oauth_client: z
      .object({
        id: z
          .string()
          .openapi({
            description: 'The ID of the OAuth client',
            example: 'AGMEB7F7YJYELCPG4Y5YWMYGXE',
          }),
        type: z
          .literal('oauth_client_reference')
          .default('oauth_client_reference')
          .openapi({
            description: 'The type of object being referenced',
            example: 'oauth_client_reference',
          }),
        summary: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'A short-form, server-generated string that provides succinct, important information about an object suitable for primary labeling of an entity in a client',
            example: 'PagerDuty Webhook Integration',
            readOnly: true,
          }),
      })
      .exactOptional()
      .openapi({
        description:
          'OAuth client details. This field is populated in responses when oauth_client_id is set.',
        readOnly: true,
        required: ['id', 'type'],
      }),
  })
  .openapi({ required: ['type', 'delivery_method', 'events', 'filter'] })
  .openapi('WebhookSubscription')

