const OrchestrationCacheVariablePostRequestRequestBody = {
  content: {
    'application/json': {
      schema: z
        .object({
          cache_variable: z.xor([
            OrchestrationCacheVariableRecentValueSchema,
            OrchestrationCacheVariableTriggerEventCountSchema,
            OrchestrationCacheVariableExternalDataSchema,
          ]),
        })
        .openapi({ required: ['cache_variable'] }),
      examples: {
        recent_value: {
          summary: 'Request Example: Recent value cache variable',
          value: {
            cache_variable: {
              name: 'example_1',
              conditions: [{ expression: 'not event.custom_details.errors exists' }],
              configuration: { type: 'recent_value', source: 'event.summary', regex: '.*' },
            },
          },
        },
        trigger_event_count: {
          summary: 'Request Example: Trigger event count cache variable',
          value: {
            cache_variable: {
              name: 'example_2',
              configuration: { type: 'trigger_event_count', ttl_seconds: 30 },
            },
          },
        },
        external_data: {
          summary: 'Request Example: External Data cache variable',
          value: {
            cache_variable: {
              name: 'example_3',
              configuration: { type: 'external_data', ttl_seconds: 300, data_type: 'boolean' },
            },
          },
        },
      },
    },
  },
}

