const EnrichmentSchemaPostRequestRequestBody = {
  description:
    'The enrichment schema to create. Provide a JSON body to define the schema explicitly, or upload a CSV file (as `multipart/form-data` or `text/csv`) to auto-generate a schema in which the first column becomes the query field and the remaining columns become enriched fields. CSV uploads are limited to 10 MB.',
  content: {
    'application/json': {
      schema: z
        .object({
          integration_type: z
            .literal('CSV')
            .exactOptional()
            .openapi({
              description:
                'The schema source. Only `CSV` is supported through the API; the schema is always recorded as `CSV` regardless of the value sent.',
            }),
          name: z
            .string()
            .max(50)
            .openapi({ description: 'Display name of the enrichment schema.' }),
          description: z
            .string()
            .max(2048)
            .exactOptional()
            .openapi({ description: 'Description of this set of enrichment data.' }),
          fields: z
            .array(
              z
                .object({
                  name: z
                    .string()
                    .max(256)
                    .openapi({
                      description:
                        'The name of the field. Must be unique within the schema (case-insensitive).',
                    }),
                  type: z
                    .enum(['query', 'enriched'])
                    .openapi({
                      description:
                        'How the field is used. `query` fields match incoming events to records (case-insensitive); `enriched` fields carry the data added to a matched event.',
                    }),
                })
                .openapi({ required: ['name', 'type'] }),
            )
            .min(2)
            .max(25)
            .openapi({
              description:
                'The schema fields. Must include 1-3 query fields and at least one enriched field, up to 25 fields total. Field names must be unique (case-insensitive).',
            }),
        })
        .openapi({ required: ['name', 'fields'] }),
      examples: {
        basic: {
          summary: 'Create a schema with multiple query fields',
          value: {
            integration_type: 'CSV',
            name: 'Application Environment Enrichment',
            description: 'Maps applications to team and runbook info by environment',
            fields: [
              { name: 'Application', type: 'query' },
              { name: 'Environment', type: 'query' },
              { name: 'Manager', type: 'enriched' },
              { name: 'Team', type: 'enriched' },
              { name: 'Runbook URL', type: 'enriched' },
            ],
          },
        },
      },
    },
    'multipart/form-data': {
      schema: z
        .object({
          file: z
            .file()
            .openapi({
              type: 'string',
              format: 'binary',
              description:
                'The CSV file to upload (max 10 MB). The schema name is derived from the filename.',
            }),
        })
        .openapi({ required: ['file'] }),
    },
    'text/csv': {
      schema: z
        .string()
        .openapi({
          description:
            'The raw CSV content (max 10 MB). Provide the filename via the `filename` query parameter.',
        }),
    },
  },
  required: true,
}

