export const postEntityTypeIdChangeTagsRoute = createRoute({
  method: 'post',
  path: '/{entity_type}/{id}/change_tags',
  tags: ['Tags'],
  summary: 'Assign tags',
  description:
    'Assign existing or new tags.\n\nA Tag is applied to Escalation Policies, Teams or Users and can be used to filter them.\n\nFor more information see the [API Concepts Document](../../api-reference/a47605517c19a-api-concepts#tags)\n\nScoped OAuth requires: `tags.write`\n',
  operationId: 'createEntityTypeByIdChangeTags',
  request: {
    headers: z.object({
      Accept: HeaderAcceptParamsSchema,
      'Content-Type': HeaderContentTypeParamsSchema,
    }),
    params: z.object({ entity_type: EntityTypeParamsSchema, id: IdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              add: z
                .array(
                  z
                    .object({
                      type: z.enum(['tag', 'tag_reference']),
                      label: z
                        .string()
                        .max(191)
                        .exactOptional()
                        .openapi({
                          description: 'The label of the tag. Should be used when type is "tag".',
                        }),
                      id: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            'The id of the tag. Should be used when type is "tag_reference".',
                          readOnly: true,
                        }),
                    })
                    .openapi({ title: 'Tags to add', required: ['type'] }),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Array of tags and/or tag references to add to the entity.\nFor elements with type `tag_reference`, the tag with the corresponding `id` is added to the entity.\nFor elements with type `tag`, if there is an existing tag with the given\nlabel that tag is added to the entity. If there is no existing tag with that label and the user has permission\nto create tags, a new tag is created with that label and assigned to the entity.\n',
                }),
              remove: z
                .array(
                  z
                    .object({
                      type: z.literal('tag_reference'),
                      id: z.string().openapi({ description: 'The id of the tag', readOnly: true }),
                    })
                    .openapi({ title: 'Tags to remove.', required: ['type', 'id'] }),
                )
                .exactOptional()
                .openapi({ description: 'Array of tag references to remove from the entity.' }),
            })
            .openapi({ description: 'Tags to add to or remove from the entity.', required: [] }),
          examples: {
            tags: {
              summary: 'Request Example',
              value: {
                add: [
                  { type: 'tag', label: 'Batman' },
                  { type: 'tag_reference', id: 'P5IYCNZ' },
                ],
                remove: [
                  { type: 'tag_reference', id: 'POE7RY8' },
                  { type: 'tag_reference', id: 'PG68P1M' },
                ],
              },
            },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'The tags were added and/or removed.',
      content: {
        'application/json': {
          schema: z.object({}),
          examples: {
            response: {
              summary: 'Request Example',
              value: {
                add: [
                  { type: 'tag', label: 'Batman' },
                  { type: 'tag_reference', id: 'P5IYCNZ' },
                ],
                remove: [
                  { type: 'tag_reference', id: 'POE7RY8' },
                  { type: 'tag_reference', id: 'PG68P1M' },
                ],
              },
            },
          },
        },
      },
    },
    400: ArgumentErrorResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    429: TooManyRequestsResponse,
  },
})

