export const getEventOrchestrationsIdRouterRoute = createRoute({
  method: 'get',
  path: '/event_orchestrations/{id}/router',
  tags: ['Event Orchestrations'],
  summary: 'Get the Router for an Event Orchestration',
  description:
    "Get a Global Orchestration's Routing Rules.\n\nAn Orchestration Router allows you to create a set of Event Rules. The Router evaluates Events you send to this Global Orchestration against each of its rules, one at a time, and routes the event to a specific Service based on the first rule that matches. If an event doesn't match any rules, it'll be sent to service specified in as the `catch_all` or the \"Unrouted\" Orchestration if no service is specified.\n\nFor more information see the [API Concepts Document](../../api-reference/a47605517c19a-api-concepts#event-orchestrations)\n\nScoped OAuth requires: `event_orchestrations.read`\n",
  operationId: 'getOrchPathRouter',
  request: {
    headers: z.object({
      Accept: HeaderAcceptParamsSchema,
      'Content-Type': HeaderContentTypeParamsSchema,
    }),
    params: z.object({ id: EventOrchestrationIdParamsSchema }),
  },
  responses: {
    200: OrchestrationPathRouterTypeResponseResponse,
    400: ArgumentErrorResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
  },
})

