export const putIncidentsIdMergeRoute = createRoute({
  method: 'put',
  path: '/incidents/{id}/merge',
  tags: ['Incidents'],
  summary: 'Merge incidents',
  description:
    "Merge a list of source incidents into the target [incident](https://developer.pagerduty.com/api-reference/a47605517c19a-api-concepts#incidents).\n\nAfter the merge is performed the target incident will contain the source incidents' [alerts](https://developer.pagerduty.com/api-reference/a47605517c19a-api-concepts#alerts),\nand the source incidents will be resolved.\n\nOnly incidents that have alerts or incidents that were created manually in the UI can be merged.\n\nOpen incidents cannot be merged into a resolved incident. The target incident must be open.\n\nAn incident cannot have more than 1000 alerts. The server will return an error if merging the source incidents\nwill result in the target incident having more than 1000 alerts.\n\nScoped OAuth requires: `incidents.write`\n",
  operationId: 'mergeIncidents',
  request: {
    headers: z.object({
      Accept: HeaderAcceptParamsSchema,
      'Content-Type': HeaderContentTypeParamsSchema,
      From: FromHeaderParamsSchema,
    }),
    params: z.object({ id: IdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              source_incidents: z
                .array(IncidentReferenceSchema)
                .openapi({
                  description:
                    'The source incidents that will be merged into the target incident and resolved.',
                }),
            })
            .openapi({ required: ['source_incidents'] }),
          examples: {
            request: {
              summary: 'Request Example',
              value: {
                source_incidents: [
                  { id: 'P8JOGX7', type: 'incident_reference' },
                  { id: 'PPVZH9X', type: 'incident_reference' },
                ],
              },
            },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description:
        'The target incident, which now contains all the alerts from the source incident.',
      content: {
        'application/json': {
          schema: z
            .object({ incident: IncidentReferenceSchema })
            .openapi({ required: ['incident'] }),
          examples: {
            response: {
              summary: 'Response Example',
              value: {
                incident: {
                  id: 'PT4KHLK',
                  type: 'incident_reference',
                  summary: '[#1234] The server is on fire.',
                  self: 'https://api.pagerduty.com/incidents/PT4KHLK',
                  html_url: 'https://subdomain.pagerduty.com/incidents/PT4KHLK',
                },
              },
            },
          },
        },
      },
    },
    400: ArgumentErrorResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
  },
})

