export const putIncidentsIdResponderRequestsCancelRoute = createRoute({
  method: 'put',
  path: '/incidents/{id}/responder_requests/cancel',
  tags: ['Incidents'],
  summary: 'Cancel responder requests for an incident',
  description:
    'Cancel pending responder requests for the specified incident.\n\nThis endpoint allows you to cancel responder requests for specified targets that are in a pending state. Only responders who have not yet joined or declined can be cancelled. This endpoint requires the account to have access to the [responder requests](https://support.pagerduty.com/main/docs/add-responders) feature.\n\n**Account Ability Requirement**: The account must have the `coordinated_responding` ability. Returns 402 Payment Required if the ability is missing. You can use the [List Abilities API](openapiv3.json/paths/~1abilities/get) to check account abilities.\n\n**State Constraints**: Only responders in the `pending` state can be cancelled. Responders who have already `joined` or `declined` are not affected (the result will indicate their current state).\n\n**User vs Escalation Policy Behavior**:\n- **Users**: Direct cancellation, updates state to `user_cancelled`, stops notifications\n- **Escalation Policies**: Stops the escalation process, updates state of all pending users from that escalation policy to `user_cancelled` and stops notifications\n\n**Result Values**:\n- `cancelled`: Successfully cancelled\n- `joined`: User already joined (not cancelled)\n- `declined`: User already declined (not cancelled)\n- `not_found`: Target not found or not part of any responder request\n\nScoped OAuth requires: `incidents.write`\n',
  operationId: 'cancelIncidentResponderRequest',
  request: {
    headers: z.object({
      Accept: HeaderAcceptParamsSchema,
      'Content-Type': HeaderContentTypeParamsSchema,
    }),
    params: z.object({ id: IdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              requester_id: z.string().openapi({ description: 'The user id of the requester.' }),
              responder_request_targets: z
                .array(
                  z
                    .object({
                      type: z
                        .enum(['user_reference', 'escalation_policy_reference'])
                        .openapi({
                          description: 'The type of target (either a user or an escalation policy)',
                        }),
                      id: z
                        .string()
                        .openapi({ description: 'The id of the user or escalation policy' }),
                    })
                    .openapi({ required: ['type', 'id'] }),
                )
                .openapi({ description: 'The array of targets to cancel.' }),
            })
            .openapi({ required: ['requester_id', 'responder_request_targets'] }),
          examples: {
            request: {
              summary: 'Request Example',
              value: {
                requester_id: 'PL1JMK5',
                responder_request_targets: [
                  { type: 'user_reference', id: 'PJ25ZYX' },
                  { type: 'escalation_policy_reference', id: 'PEP12AB' },
                ],
              },
            },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'The result of cancelling responder requests for the given incident.',
      content: {
        'application/json': {
          schema: z
            .object({
              responder_request_targets: z
                .array(
                  z
                    .object({
                      type: z
                        .enum(['user_reference', 'escalation_policy_reference'])
                        .openapi({
                          description: 'The type of target (either a user or an escalation policy)',
                        }),
                      id: z
                        .string()
                        .openapi({ description: 'The id of the user or escalation policy' }),
                      result: z
                        .enum(['cancelled', 'joined', 'declined', 'not_found'])
                        .openapi({ description: 'The result of the cancellation attempt' }),
                    })
                    .openapi({ required: ['type', 'id', 'result'] }),
                )
                .openapi({ description: 'The array of targets with their cancellation results.' }),
            })
            .openapi({ required: ['responder_request_targets'] }),
          examples: {
            all_cancelled: {
              summary: 'All Targets Cancelled',
              value: {
                responder_request_targets: [
                  { type: 'user_reference', id: 'PJ25ZYX', result: 'cancelled' },
                  { type: 'escalation_policy_reference', id: 'PEP12AB', result: 'cancelled' },
                ],
              },
            },
            mixed_results: {
              summary: 'Mixed Results',
              value: {
                responder_request_targets: [
                  { type: 'user_reference', id: 'PJ25ZYX', result: 'cancelled' },
                  { type: 'user_reference', id: 'PL7A2O4', result: 'joined' },
                  { type: 'user_reference', id: 'PABC123', result: 'not_found' },
                ],
              },
            },
          },
        },
      },
    },
    400: ArgumentErrorResponse,
    401: UnauthorizedResponse,
    402: PaymentRequiredResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
  },
})

