export const getIncidentsIdScribeTranscriptsRoute = createRoute({
  method: 'get',
  path: '/incidents/{id}/scribe_transcripts',
  tags: ['Incidents'],
  summary: 'Get Scribe transcripts for an incident',
  description:
    'Get download links for the Scribe transcripts of the specified incident. Only Scribes that have completed are returned; a Scribe that is still in progress does not appear in the response.\n\nEach entry contains a presigned `download_url` for a single transcript format, selected with the `format` query parameter (`enhanced` by default, or `raw`). \n\nThe `download_url` is time-limited and expires after one hour, so request a new one if it has expired. `download_url` is `null` when the transcript is not available for the requested format.\n\nScoped OAuth requires: `incidents.read`\n',
  operationId: 'getIncidentScribeTranscripts',
  request: {
    headers: z.object({
      Accept: HeaderAcceptParamsSchema,
      'Content-Type': HeaderContentTypeParamsSchema,
    }),
    params: z.object({ id: IdParamsSchema }),
    query: z.object({ format: ScribeTranscriptFormatParamsSchema }),
  },
  responses: {
    200: {
      description: 'The completed Scribe transcripts for the specified incident.',
      content: {
        'application/json': {
          schema: z
            .object({
              scribe_transcripts: z
                .array(
                  z
                    .object({
                      scribe_id: z.string().openapi({ description: 'The ID of the Scribe.' }),
                      format: z
                        .enum(['enhanced', 'raw'])
                        .openapi({
                          description: 'The transcript format that `download_url` corresponds to.',
                        }),
                      started_at: z.iso
                        .datetime({ offset: true })
                        .exactOptional()
                        .openapi({ description: 'The time the Scribe started.' }),
                      ended_at: z.iso
                        .datetime({ offset: true })
                        .nullable()
                        .exactOptional()
                        .openapi({ description: 'The time the Scribe ended.' }),
                      download_url: z
                        .string()
                        .nullable()
                        .openapi({
                          description:
                            'A presigned URL to download the transcript. Expires after one hour. `null` if the transcript is not available.',
                        }),
                    })
                    .openapi({ required: ['scribe_id', 'format', 'download_url'] }),
                )
                .openapi({ description: 'The Scribe transcripts associated with the incident.' }),
            })
            .openapi({ required: ['scribe_transcripts'] }),
          examples: {
            response: {
              summary: 'Response Example',
              value: {
                scribe_transcripts: [
                  {
                    format: 'enhanced',
                    started_at: '2026-09-28T09:22:57.896Z',
                    scribe_id: 'AGQOOUXTMR3TPA3ULKC7KHPZCQ',
                    ended_at: '2026-09-28T09:24:50.097Z',
                    download_url:
                      'https://s3.us-west-2.amazonaws.com/example-bucket/AGQOOUXTMR3TPA3ULKC7KHPZCQ_enhanced_transcript.json?X-Amz-Expires=3600&X-Amz-Signature=EXAMPLE',
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: ArgumentErrorResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
  },
})

