export const postIncidentsIdStatusUpdatesSubscribersRoute = createRoute({
  method: 'post',
  path: '/incidents/{id}/status_updates/subscribers',
  tags: ['Incidents'],
  summary: 'Add Notification Subscribers',
  description:
    'Subscribe the given entities to Incident Status Update Notifications.\n\nScoped OAuth requires: `subscribers.write`\n',
  operationId: 'createIncidentNotificationSubscribers',
  request: {
    headers: z.object({ Accept: HeaderAcceptParamsSchema }),
    params: z.object({ id: IdParamsSchema }),
    body: {
      description: 'The entities to subscribe.',
      content: {
        'application/json': {
          schema: z
            .object({
              subscribers: z
                .array(NotificationSubscriberSchema)
                .min(1)
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                }),
            })
            .openapi({ required: ['subscribers'] }),
          examples: {
            request: {
              summary: 'Request Example',
              value: {
                subscribers: [
                  { subscriber_id: 'PD1234', subscriber_type: 'team' },
                  { subscriber_id: 'PD1235', subscriber_type: 'team' },
                  { subscriber_id: 'PD1234', subscriber_type: 'user' },
                ],
              },
            },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .object({
              subscriptions: z.array(NotificationSubscriptionWithContextSchema).exactOptional(),
            })
            .openapi({ required: [] }),
          examples: {
            response: {
              summary: 'Response Example',
              value: {
                subscriptions: [
                  {
                    account_id: 'PD1234',
                    subscribable_id: 'PD1234',
                    subscribable_type: 'incident',
                    subscriber_id: 'PD1234',
                    subscriber_type: 'user',
                    result: 'success',
                  },
                  {
                    account_id: 'PD1234',
                    subscribable_id: 'PD1234',
                    subscribable_type: 'incident',
                    subscriber_id: 'PD1234',
                    subscriber_type: 'team',
                    result: 'duplicate',
                  },
                  {
                    account_id: 'PD1234',
                    subscribable_id: 'PD1235',
                    subscribable_type: 'incident',
                    subscriber_id: 'PD1234',
                    subscriber_type: 'team',
                    result: 'unauthorized',
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: ArgumentErrorResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    422: UnprocessableEntityResponse,
  },
})

