export const deleteOauthDelegationsRoute = createRoute({
  method: 'delete',
  path: '/oauth_delegations',
  tags: ['OAuth Delegations'],
  summary: 'Delete all OAuth delegations',
  description:
    "Delete all OAuth delegations as per provided query parameters.\n\nAn OAuth delegation represents an instance of a user or account's authorization to an app (via OAuth) to access their PagerDuty account.\nCommon apps include the PagerDuty mobile app, Slack, Microsoft Teams, and third-party apps. It also represents a user session in the PagerDuty web app.\n\nDeleting an OAuth delegation will revoke that instance of an app's access to that user or account.\nTo grant access again, reauthorization/reauthentication will be required.\n\nThis endpoint supports deleting mobile app OAuth delegations for a given user, which is equivalent to signing users out of the mobile app. It also supports deleting delegations of type web, which is equivalent to signing users out of the web app.\n\nThis is a synchronous API.\n\nScoped OAuth requires: `oauth_delegations.write`\n",
  operationId: 'deleteOauthDelegations',
  request: {
    headers: z.object({
      Accept: HeaderAcceptParamsSchema,
      'Content-Type': HeaderContentTypeParamsSchema,
    }),
    query: z.object({
      user_id: OauthDelegationUserIdParamsSchema,
      type: OauthDelegationTypeParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'The request to delete delegations has been processed.',
      content: {
        'application/json': {
          schema: z
            .object({ status: z.string().exactOptional().openapi({ example: 'ok' }) })
            .openapi({ required: [] }),
          examples: { response: { summary: 'Response Example', value: { status: 'ok' } } },
        },
      },
    },
    400: ArgumentErrorResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    429: TooManyRequestsResponse,
  },
})

