export const postServicesIdRulesConvertRoute = createRoute({
  method: 'post',
  path: '/services/{id}/rules/convert',
  tags: ['Services'],
  summary: "Convert a Service's Event Rules into Event Orchestration Rules",
  description:
    "Convert this Service's Event Rules into functionally equivalent Event Orchestration Rules.\n\nSending a request to this API endpoint has several effects:\n\n1. Automatically creates Event Orchestration Rules for this Service that will behave identically as this Service's currently configured Event Rules.\n2. Makes all existing Event Rules for this Service read-only. All future updates need to be made via the newly created Event Orchestration rules.\n\nSending a request to this API endpoint will **not** change how future events will be processed. If past events for this Service have been evaluated via Event Rules then new events sent to this Service will also continue to be evaluated via the (now read-only) Event Rules. To change this Service so that new events start being evaluated via the newly created Event Orchestration Rules use the [Update the Service Orchestration active status for a Service API](https://developer.pagerduty.com/api-reference/855659be83d9e-update-the-service-orchestration-active-status-for-a-service).\n\n> ### End-of-life\n> Event Rules will end-of-life soon. We highly recommend that you use this API to [migrate to Event Orchestration](https://support.pagerduty.com/docs/migrate-to-event-orchestration) as soon as possible so you can take advantage of the new functionality, such as improved UI, rule creation, APIs and Terraform support, advanced conditions, and rule nesting.\n\nScoped OAuth requires: `services.write`\n",
  operationId: 'convertServiceEventRulesToEventOrchestration',
  request: {
    headers: z.object({
      Accept: HeaderAcceptParamsSchema,
      'Content-Type': HeaderContentTypeParamsSchema,
    }),
    params: z.object({ id: IdParamsSchema }),
  },
  responses: {
    200: {
      description: 'The Event Orchestration Rules were successfully created',
      content: {
        'application/json': {
          schema: z
            .object({
              convert_status: z
                .string()
                .exactOptional()
                .openapi({
                  readOnly: true,
                  description:
                    'Did PagerDuty successfully create equivalent Event Orchestration rules',
                }),
              converted_to: z
                .url()
                .exactOptional()
                .openapi({
                  readOnly: true,
                  description:
                    'the API URL at which the newly created Event Orchestration rules are accessible',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            response: {
              summary: 'Response Example',
              value: {
                convert_status: 'completed',
                converted_to: 'https://api.pagerduty.com/event_orchestrations/service/PC2D9ML',
              },
            },
          },
        },
      },
    },
    400: {
      description:
        "Could not create equivalent Event Orchestration Rules based on the Service's current Event Rules",
      content: {
        'application/json': {
          schema: z
            .object({
              error: z
                .object({
                  message: z
                    .string()
                    .exactOptional()
                    .openapi({ readOnly: true, description: 'Error message string' }),
                  errors: z
                    .array(
                      z
                        .object({
                          rule_id: z
                            .string()
                            .exactOptional()
                            .openapi({
                              readOnly: true,
                              description:
                                "The ID of the Service Event Rule that couldn't be successfully converted.",
                            }),
                          position: z
                            .int()
                            .exactOptional()
                            .openapi({
                              readOnly: true,
                              description:
                                "The position of the Service Event Rule that couldn't be successfully converted.",
                            }),
                          messages: z
                            .array(z.string().openapi({ readOnly: true }))
                            .exactOptional()
                            .openapi({
                              readOnly: true,
                              description:
                                "Human friendly explanations of why this Event Rule couldn't be converted into an equivalent Event Orchestration Rule.",
                            }),
                        })
                        .openapi({
                          readOnly: true,
                          description: 'Convertion error Details',
                          required: [],
                        }),
                    )
                    .exactOptional()
                    .openapi({ readOnly: true }),
                })
                .exactOptional()
                .openapi({ readOnly: true, required: [] }),
            })
            .openapi({ readOnly: true, required: [] }),
          examples: {
            response: {
              summary: 'Response Example',
              value: {
                error: {
                  message: 'Unable to convert given Ruleset to an Event Orchestration',
                  errors: [
                    {
                      rule_id: '693cdcd1-ecfd-4064-a834-5cb28a74c060',
                      position: 0,
                      messages: [
                        'Unable to convert a rule that has a `time_frame` with both `active_between` and `scheduled_weekly` settings.',
                      ],
                    },
                    {
                      rule_id: '9f6896c0-b435-401f-b25f-62e145d9ccf4',
                      position: 5,
                      messages: [
                        'Unable to convert `actions.extractions`; Should have a most 25 extractions but this rule has 42 extractions.',
                      ],
                    },
                  ],
                },
              },
            },
          },
        },
      },
    },
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    405: NotAllowedResponse,
    409: ConflictResponse,
  },
})

