export const getSessionConfigurationsRoute = createRoute({
  method: 'get',
  path: '/session_configurations',
  tags: ['Session Configurations'],
  summary: "Get an account's session configurations",
  description:
    'Retrieves session configurations for a PagerDuty account. Returns an array containing\nthe requested configurations. If a specific type is requested, the array contains one item.\nIf no type is specified, the array contains all available configurations (mobile and web).\nIf no configurations exist, a 404 Not Found error will be returned.\n\nA Session Configuration needs to be created before it can be retrieved and used.\n\nScoped OAuth requires: `session_configurations.read`\n',
  operationId: 'getSessionConfigurations',
  request: {
    headers: z.object({
      Accept: HeaderAcceptParamsSchema,
      'Content-Type': HeaderContentTypeParamsSchema,
    }),
    query: z.object({ type: OptionalSessionConfigurationTypeParamsSchema }),
  },
  responses: {
    200: {
      description: 'Session Configurations retrieved successfully',
      content: {
        'application/json': {
          schema: z
            .object({
              session_configurations: z.array(
                z
                  .object({
                    type: z
                      .enum(['mobile', 'web'])
                      .openapi({
                        description: 'The session configuration type (mobile or web)',
                        example: 'web',
                      }),
                    absolute_session_ttl: z
                      .int()
                      .min(600)
                      .max(18144000)
                      .openapi({
                        description: 'Absolute session time to live in seconds',
                        example: 3600,
                      }),
                    idle_session_ttl: z
                      .int()
                      .min(60)
                      .max(86400)
                      .openapi({
                        description: 'Idle session time to live in seconds',
                        example: 1800,
                      }),
                  })
                  .openapi({ required: ['type', 'absolute_session_ttl', 'idle_session_ttl'] }),
              ),
            })
            .openapi({ required: ['session_configurations'] }),
          examples: {
            response: {
              summary: 'Session Configurations Example',
              value: {
                session_configurations: [
                  { type: 'web', absolute_session_ttl: 3600, idle_session_ttl: 600 },
                  { type: 'mobile', absolute_session_ttl: 7200, idle_session_ttl: 1200 },
                ],
              },
            },
          },
        },
      },
    },
    400: ArgumentErrorResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
  },
})

