export const getStatusDashboardsIdServiceImpactsRoute = createRoute({
  method: 'get',
  path: '/status_dashboards/{id}/service_impacts',
  tags: ['Status Dashboards'],
  summary: 'Get impacted Business Services for a Status Dashboard by `id`.',
  description:
    'Get impacted Business Services for a Status Dashboard by `id`\n\nThis endpoint does not return an exhaustive list of Business Services but rather provides access to the most impacted on the specified Status Dashboard up to the limit of 200.\n\nThe returned Business Services are sorted first by Impact, secondarily by most recently impacted, and finally by name.\n\nTo get Impact information about a specific Business Service on the Status Dashboard that does not appear in the Impact-sorted response, use the `ids[]` parameter on the `/business_services/impacts` endpoint.\n\nScoped OAuth requires: `status_dashboards.read`\n',
  operationId: 'getStatusDashboardServiceImpactsById',
  request: {
    headers: z.object({ Accept: HeaderAcceptParamsSchema }),
    params: z.object({ id: IdParamsSchema }),
    query: z.object({ 'additional_fields[]': ImpactsAdditionalFieldsParamsSchema }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: LiveListResponseSchema.and(
            z.object({ services: z.array(ImpactSchema).exactOptional() }).openapi({ required: [] }),
          ).and(
            z
              .object({
                additional_fields: z
                  .object({ total_impacted_count: z.int().exactOptional() })
                  .exactOptional()
                  .openapi({ required: [] }),
              })
              .openapi({ required: [] }),
          ),
          examples: {
            response: {
              summary: 'Response Example',
              value: {
                limit: 100,
                more: false,
                services: [
                  {
                    id: 'PD1234',
                    name: 'Web API',
                    type: 'business_service',
                    status: 'impacted',
                    additional_fields: {
                      highest_impacting_priority: { id: 'PQOMK4S', order: 128 },
                    },
                  },
                  {
                    id: 'PF9KMXH',
                    name: 'Analytics Backend',
                    type: 'business_service',
                    status: 'not_impacted',
                    additional_fields: { highest_impacting_priority: null },
                  },
                ],
                additional_fields: { total_impacted_count: 1 },
              },
            },
          },
        },
      },
    },
    400: ArgumentErrorResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    422: UnprocessableEntityResponse,
    429: TooManyRequestsResponse,
  },
})

