export const postUsersIdRegeneratePrivateUrlKeyRoute = createRoute({
  method: 'post',
  path: '/users/{id}/regenerate_private_url_key',
  tags: ['Users'],
  summary: "Regenerate a user's calendar feed URL key",
  description:
    "Regenerate the private URL key used to construct a user's personal iCal calendar feed URLs\n(`http_cal_url` and `web_cal_url`). The old key is immediately invalidated; callers should\nupdate any stored feed subscriptions with the new key.\n\nA user may only regenerate their own key. Account admins may regenerate on behalf of any user.\n\nThe calendar feed URLs act as bearer credentials: anyone with the URL can read that user's\non-call calendar without further authentication. Rotate the key here whenever a URL may\nhave been exposed (for example, if it was shared outside the intended audience or if an\nadmin with `can_update_user` retrieved it via `GET /users/{id}?include[]=calendar_urls`).\n\nUsers are members of a PagerDuty account that have the ability to interact with Incidents and\nother data on the account.\n\nFor more information see the [API Concepts Document](../../api-reference/a47605517c19a-api-concepts#users)\n\nScoped OAuth requires: `users.write`\n",
  operationId: 'regenerateUserPrivateUrlKey',
  request: {
    headers: z.object({
      Accept: HeaderAcceptParamsSchema,
      'Content-Type': HeaderContentTypeParamsSchema,
    }),
    params: z.object({ id: IdParamsSchema }),
  },
  responses: {
    200: {
      description: "The user's new private URL key.",
      content: {
        'application/json': {
          schema: z
            .object({
              private_url_key: z
                .string()
                .openapi({
                  description: 'The newly generated private URL key for calendar feed URLs.',
                }),
            })
            .openapi({ required: ['private_url_key'] }),
          examples: {
            response: {
              summary: 'Response Example',
              value: { private_url_key: 'ABCDEFGHIJKLMNOP' },
            },
          },
        },
      },
    },
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
  },
})

