export const getV3SchedulesRoute = createRoute({
  method: 'get',
  path: '/v3/schedules',
  tags: ['Schedules_v3'],
  summary: 'List schedules',
  description:
    "<!-- theme: info -->\n\n> **Important note:** Shift-based schedules use the V3 API and are not compatible with V2 automations. **To create automations for Shift-Based Schedules, you need to:**\n>\n> 1. **Update your automations** to use the V3 API for all new shift-based schedules\n> 2. **Keep the V2 endpoint** for your existing schedules\n>\n> An upgrade tool for existing schedules is coming soon; your legacy schedules will keep working in the meantime. [Learn more](https://support.pagerduty.com/main/docs/shift-based-schedules-api-upgrade-examples).\n\nRetrieve a paginated list of schedule references. Returns lightweight\nobjects without embedded rotations or events.\n\nEach result is filtered by the caller's read permission; schedules the\ncaller cannot read are silently excluded.\n",
  operationId: 'listSchedulesV3',
  request: {
    query: z.object({
      limit: ScheduleV3LimitSchedulesParamsSchema,
      offset: ScheduleV3OffsetParamsSchema,
      query: QueryParamsSchema,
      total: OffsetTotalParamsSchema,
      'team_ids[]': TeamIdsParamsSchema,
      user_id: ScheduleV3UserIdParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Schedules retrieved successfully',
      content: {
        'application/json': {
          schema: z
            .object({
              schedules: z.array(V3ScheduleReferenceSchema),
              limit: z.int().exactOptional().openapi({ example: 100 }),
              offset: z.int().exactOptional().openapi({ example: 0 }),
              more: z
                .boolean()
                .exactOptional()
                .openapi({
                  description: 'Whether additional results exist beyond this page',
                  example: false,
                }),
            })
            .openapi({ required: ['schedules'] }),
          examples: {
            response: {
              summary: 'Example response',
              value: {
                schedules: [
                  {
                    id: 'PS1A2B3C',
                    type: 'schedule_v3_reference',
                    summary: 'Engineering On-Call',
                    self: 'https://api.pagerduty.com/v3/schedules/PS1A2B3C',
                    html_url: 'https://subdomain.pagerduty.com/schedules/PS1A2B3C',
                  },
                ],
                limit: 100,
                offset: 0,
                more: false,
              },
            },
          },
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    500: InternalServerErrorResponse,
  },
})

